import React, { useState, useEffect, useContext } from 'react';
import EventForm from './EventForm';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';

const Dashboard = () => {
  const [events, setEvents] = useState([]);
  const [allUsers, setAllUsers] = useState([]); // Store all possible users
  const [showForm, setShowForm] = useState(false);
  const [expandedEvent, setExpandedEvent] = useState(null);
  const [newItemName, setNewItemName] = useState("");
  const { user, logout } = useContext(AuthContext) || {};
  const navigate = useNavigate();

  const currentUserId = user?.id || user?._id;
  const API_BASE = `http://${window.location.hostname}:5000/api/events`;

  const fetchData = async () => {
    if (!currentUserId) return;
    try {
      const [eventsRes, usersRes] = await Promise.all([
        axios.get(`${API_BASE}?userId=${currentUserId}`),
        axios.get(`${API_BASE}/users`)
      ]);
      setEvents(eventsRes.data);
      setAllUsers(usersRes.data);
      if (expandedEvent) {
        const updated = eventsRes.data.find(e => e._id === expandedEvent._id);
        setExpandedEvent(updated);
      }
    } catch (err) { console.error(err); }
  };

  useEffect(() => { fetchData(); }, [currentUserId]);

  const handleRSVP = async (e, eventId, status) => {
    e.stopPropagation();
    try {
      await axios.post(`${API_BASE}/${eventId}/rsvp`, { userId: currentUserId, status });
      fetchData();
    } catch (err) { alert(err.response?.data?.message || "Error"); }
  };

  const handleInvite = async (eventId, guestId) => {
    try {
      await axios.post(`${API_BASE}/${eventId}/invite`, { guestId });
      alert("Invited!");
      fetchData();
    } catch (err) { alert("Error inviting"); }
  };

  const handleDeleteEvent = async (e, eventId) => {
    e.stopPropagation();
    if (!window.confirm("Delete event?")) return;
    try {
      await axios.delete(`${API_BASE}/${eventId}?userId=${currentUserId}`);
      fetchData();
    } catch (err) { alert("Error deleting"); }
  };

  const handleAddItem = async (e, eventId) => {
    e.preventDefault();
    try {
      await axios.post(`${API_BASE}/${eventId}/items`, { itemName: newItemName, userId: currentUserId, userName: user.name });
      setNewItemName("");
      fetchData();
    } catch (err) { alert("Error"); }
  };

  const styles = {
    container: { minHeight: '100vh', background: 'linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)', padding: '40px 20px', fontFamily: 'sans-serif' },
    wrapper: { maxWidth: '1100px', margin: '0 auto' },
    card: { backgroundColor: 'white', padding: '20px', borderRadius: '16px', boxShadow: '0 4px 15px rgba(0,0,0,0.1)', cursor: 'pointer', position: 'relative' },
    grid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '24px' },
    modalOverlay: { position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 },
    modal: { background: 'white', padding: '30px', borderRadius: '20px', width: '90%', maxWidth: '500px', maxHeight: '80vh', overflowY: 'auto' },
    rsvpGroup: { display: 'flex', gap: '10px', marginTop: '15px' },
    btnComing: (active) => ({ flex: 1, padding: '10px', borderRadius: '8px', border: 'none', cursor: 'pointer', fontWeight: 'bold', backgroundColor: active ? '#00b894' : '#f0f2f5', color: active ? 'white' : '#636e72' }),
    btnNotComing: (active, disabled) => ({ flex: 1, padding: '10px', borderRadius: '8px', border: 'none', cursor: disabled ? 'not-allowed' : 'pointer', fontWeight: 'bold', backgroundColor: active ? '#ff7675' : '#f0f2f5', color: active ? 'white' : '#636e72', opacity: disabled ? 0.5 : 1 })
  };

  return (
    <div style={styles.container}>
      <div style={styles.wrapper}>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '40px' }}>
          <h1>Dashboard</h1>
          <button onClick={() => { logout(); navigate('/'); }} style={{ padding: '10px', background: '#ff6b6b', color: 'white', border: 'none', borderRadius: '8px' }}>Logout</button>
        </div>

        <button onClick={() => setShowForm(!showForm)} style={{ padding: '12px 24px', background: '#6c5ce7', color: 'white', border: 'none', borderRadius: '10px', marginBottom: '30px' }}>
          {showForm ? "✕ Close" : "+ Create Event"}
        </button>

        {showForm && <div style={{ background: 'white', padding: '20px', borderRadius: '15px', marginBottom: '30px' }}><EventForm user={user} onEventCreated={() => { fetchData(); setShowForm(false); }} /></div>}

        <div style={styles.grid}>
          {events.map(e => {
            const isCreator = String(e.creator?._id || e.creator) === String(currentUserId);
            const isAttending = e.attendees?.some(a => String(a._id || a) === String(currentUserId));
            return (
              <div key={e._id} style={styles.card} onClick={() => setExpandedEvent(e)}>
                {isCreator && <button style={{ position: 'absolute', top: 15, right: 15, border: 'none', background: 'none', color: 'red' }} onClick={(ev) => handleDeleteEvent(ev, e._id)}>✕</button>}
                <h3>{e.name}</h3>
                <p>📍 {e.location}</p>
                <div style={styles.rsvpGroup}>
                  <button style={styles.btnComing(isAttending)} onClick={(ev) => handleRSVP(ev, e._id, 'coming')}>✓ Coming</button>
                  <button disabled={isCreator} style={styles.btnNotComing(!isAttending && !isCreator, isCreator)} onClick={(ev) => !isCreator && handleRSVP(ev, e._id, 'not-coming')}>{isCreator ? "Organizer" : "✕ Not Coming"}</button>
                </div>
              </div>
            );
          })}
        </div>

        {expandedEvent && (
          <div style={styles.modalOverlay} onClick={() => setExpandedEvent(null)}>
            <div style={styles.modal} onClick={e => e.stopPropagation()}>
              <h2>{expandedEvent.name}</h2>
              
              {/* INVITE NEW USERS SECTION */}
              {String(expandedEvent.creator?._id || expandedEvent.creator) === String(currentUserId) && (
                <div style={{ marginTop: '20px' }}>
                  <h4>Invite Friends:</h4>
                  <div style={{ maxHeight: '100px', overflowY: 'auto', border: '1px solid #ddd', padding: '10px', borderRadius: '8px' }}>
                    {allUsers.filter(u => u._id !== currentUserId && !expandedEvent.invitedGuests?.includes(u._id)).map(u => (
                      <div key={u._id} style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '5px' }}>
                        <span>{u.name}</span>
                        <button onClick={() => handleInvite(expandedEvent._id, u._id)} style={{ background: '#6c5ce7', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>Invite</button>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              <h4 style={{ marginTop: '20px' }}>Coming:</h4>
              <div style={{ display: 'flex', gap: '5px', flexWrap: 'wrap' }}>
                {expandedEvent.attendees?.map(a => <span key={a._id} style={{ background: '#dfe6e9', padding: '5px 10px', borderRadius: '10px', fontSize: '12px' }}>{a.name}</span>)}
              </div>

              <button onClick={() => setExpandedEvent(null)} style={{ width: '100%', padding: '10px', background: '#f0f2f5', border: 'none', borderRadius: '8px', marginTop: '20px' }}>Close</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
